// Launch chrome with the extension + check the extension's background worker target.
const proc = new Deno.Command("/usr/bin/chromium", {
  args: ["--headless=new", "--no-sandbox", "--disable-gpu", "--disable-dev-shm-usage",
    "--user-data-dir=/tmp/cap-load-test2", "--remote-debugging-port=0",
    "--load-extension=/home/paulkinlan/chrome-agent-platform/extension",
    "--disable-extensions-except=/home/paulkinlan/chrome-agent-platform/extension",
    "about:blank"],
  stdout: "piped", stderr: "piped",
}).spawn();
let port = 0;
for (let i = 0; i < 40; i++) {
  await new Promise((r) => setTimeout(r, 250));
  const r = proc.stderr.getReader();
  const { value, done } = await r.read(); r.releaseLock();
  const line = done ? null : new TextDecoder().decode(value);
  if (line?.includes("DevTools listening")) { port = Number(line.match(/ws:\/\/127\.0\.0\.1:(\d+)/)?.[1] ?? 0); break; }
}
const list = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
const ext = list.filter((t) => t.type === "service_worker" && t.url.includes("chrome-extension"));
console.log("extension service-worker targets:", ext.length);
for (const t of ext) console.log(" -", t.url);
// Also check the extension is registered via the browser target.
const version = await (await fetch(`http://127.0.0.1:${port}/json/version`)).json();
console.log("browser:", version.Browser);
proc.kill();
Deno.exit(0);
EOF
